/** Request from the Apparatus to place a source beside its supporting claim. */
export interface CitationInsertionDetail {
  sourceId: string;
  text: string;
  /** Verbatim draft passage the research source was found for. */
  anchor?: string;
  /** Used only when the bibliography entry was created from an inline URL. */
  sourceUrl?: string;
  /** Manual insertion may use a selected passage when no saved anchor exists. */
  allowSelectionFallback?: boolean;
}

export interface CitationInsertionResult {
  sourceId: string;
  inserted: boolean;
  reason?: "anchor-not-found" | "select-passage";
}

/**
 * What kind of thing in a draft the Apparatus decides needs backing up.
 * The extractor (not a regex) chooses this per passage — works include
 * films, books, songs and plays; statistics are numeric claims; quotes
 * are attributed speech, however the draft found it.
 */
export type ResearchTargetKind =
  | "quote"
  | "work"
  | "person"
  | "statistic"
  | "claim"
  | "event";

/**
 * A citable thing the background agent pulled out of the draft. It is the
 * unit of auto-research: the apparatus hunts a source for exactly one of
 * these at a time, instead of googling the whole essay.
 */
export interface ResearchTarget {
  /** Stable id for the pass (used for UI keys, not persistence). */
  id: string;
  kind: ResearchTargetKind;
  /** The passage verbatim just as it appears in the draft. */
  anchor: string;
  /** Why this specific thing should not stand uncited. */
  reason: string;
  /** The precise query the search providers should receive for this target. */
  query: string;
  /** 1 (nice-to-have) to 5 (the argument collapses without it). */
  importance: number;
}

/** The target a background-saved bibliography entry was found for. */
export interface ResearchTargetRef {
  kind: ResearchTargetKind;
  anchor: string;
  query: string;
  reason?: string;
}

export interface DroppedAsset {
  type: "image" | "table" | "plot";
  data: string;
  position: number;
  caption?: string;
  metadata?: Record<string, string>;
}

export interface DocumentMeta {
  title: string;
  wordCount: number;
  characterCount: number;
  readingTime: number;
}

/**
 * Payload of the `twyne:content` event.
 *
 * Everything here is derived once, from the ProseMirror document, at the point
 * the editor already has it in hand. Listeners must not re-derive prose or
 * word counts by running regexes back over `html` — that used to happen three
 * separate times per keystroke, each allocating a fresh copy of the entire

export const DEFAULT_WRITER_SETTINGS: WriterSettings = {
  interviewStyle: "form",
  profile: { ...DEFAULT_WRITER_PROFILE },
};

export type ApparatusCitationStyle = "mla" | "apa" | "chicago";

/**
 * Where claim-checking searches go.
 *
 *  - hosted:           Twyne's own service, using the server's provider key.
 *  - search-api:       a search API called straight from this browser (BYOK),
 *                      configured by `searchBackend`.
 *  - model-web-search: the writer's own model provider, with web search on.
 *  - web-mcp:          tools discovered from the writer's MCP servers.
 */
export type ApparatusResearchProvider =
  | "hosted"
  | "search-api"
  | "model-web-search"
  | "web-mcp";

/**
 * Search APIs Twyne knows how to speak without configuration. "custom" covers
 * anything else that returns JSON: give it a URL and where the results live.
 */
export type SearchBackendId =
  | "tinyfish"
  | "exa"
  | "tavily"
  | "brave"
  | "serper"
  | "custom";

export interface SearchBackendConfig {
  id: SearchBackendId;
  apiKey: string;
  /** Overrides the adapter's built-in endpoint. Required for "custom". */
  baseUrl: string;
  /**
   * "custom" only: dotted path to the results array in the response
   * (e.g. "data.results"). Empty means search the response for the first
   * array of objects that carry a url.
   */
  resultsPath: string;
}

export const DEFAULT_SEARCH_BACKEND: SearchBackendConfig = {
  id: "tinyfish",
  apiKey: "",
  baseUrl: "",
  resultsPath: "",
};

/** Streamable HTTP is the current spec transport; SSE is the deprecated one. */
export type McpTransportKind = "http" | "sse";

/**
 * How to reach the server. Most hosted MCP servers send no CORS headers, so
 * "auto" tries the browser first (token stays on the device) and relays through
 * Convex only once a direct attempt has failed.
 */
export type McpConnectionMode = "auto" | "direct" | "proxy";

export interface McpServerConfig {
  id: string;
  label: string;
  url: string;
  transport: McpTransportKind;
  bearerToken: string;
  enabled: boolean;
  connection: McpConnectionMode;
  /** Tool that answers apparatus claim searches. Empty means auto-detect. */
  searchToolName: string;
  /** Offer this server's tools to the model while drafting. */
  exposeToModel: boolean;
  /** Treat this server's resources as citable knowledge-base material. */
  useResources: boolean;
}

export const DEFAULT_MCP_SERVER: Omit<McpServerConfig, "id"> = {
  label: "",
  url: "",
  transport: "http",
  bearerToken: "",
  enabled: true,
  connection: "auto",
  searchToolName: "",
  exposeToModel: false,
  useResources: true,
};

export interface ApparatusSettings {
  defaultCitationStyle: ApparatusCitationStyle;
  aiEnhanceCitations: boolean;
  flagMissingSources: boolean;
  /** Insert newly researched sources as footnotes at their draft anchors. */
  autoInsertFootnotes: boolean;
  researchProvider: ApparatusResearchProvider;
  searchBackend: SearchBackendConfig;
  /** Sources requested per claim, whichever provider answers. */
  maxResults: number;
  mcpServers: McpServerConfig[];
}

export const DEFAULT_APPARATUS_SETTINGS: ApparatusSettings = {
  defaultCitationStyle: "mla",
  aiEnhanceCitations: true,
  flagMissingSources: false,
  autoInsertFootnotes: false,
  researchProvider: "hosted",
  searchBackend: { ...DEFAULT_SEARCH_BACKEND },
  maxResults: 8,
  mcpServers: [],
};

export interface AiFeatureOverride {
  providerId?: string;
  model?: string;
  temperature?: number;
  maxTokens?: number;
  voice?: string;
  speed?: number;
  responseFormat?: "mp3" | "opus" | "aac" | "flac" | "wav" | "pcm";
  instructions?: string;
}

export interface AiSettings {
  advancedMode: boolean;
  providers: AiProviderConfig[];

