1	/**
2	 * Search backends for the Apparatus.
3	 *
4	 * Claim-checking needs one thing from a search API — turn a query into sources
5	 * — and every vendor spells that differently. Each adapter here owns the two
6	 * places the differences live: how the request is built, and where the results
7	 * hide in the response. Everything downstream sees `Source[]`.
8	 *
9	 * Adding a vendor means adding an entry to `SEARCH_BACKENDS`. Nothing in the
10	 * research loop, the settings UI, or the citation code needs to change.
11	 */
12	
13	import type { Source } from "../../convex/research";
14	import type { SearchBackendConfig, SearchBackendId } from "../types";
15	
16	export interface SearchRequest {
17	  query: string;
18	  context: string;
19	  maxResults: number;
20	}
21	
22	export interface SearchBackendAdapter {
23	  id: SearchBackendId;
24	  label: string;
25	  /** Shown in settings so the writer knows where to get a key. */
26	  keyHint: string;
27	  defaultUrl: string;
28	  /** Whether the writer must supply their own endpoint. */
29	  requiresUrl?: boolean;
30	  buildRequest(
31	    req: SearchRequest,
32	    config: SearchBackendConfig,
33	  ): { url: string; init: RequestInit };
34	  /** Pull the result array out of the parsed response body. */
35	  extract(body: unknown, config: SearchBackendConfig): unknown;
36	}
37	
38	function jsonPost(
39	  url: string,
40	  headers: Record<string, string>,
41	  body: unknown,
42	): { url: string; init: RequestInit } {
43	  return {
44	    url,
45	    init: {
46	      method: "POST",
47	      headers: { "content-type": "application/json", ...headers },
48	      body: JSON.stringify(body),
49	    },
50	  };
51	}
52	
53	function endpoint(config: SearchBackendConfig, fallback: string): string {
54	  const custom = config.baseUrl.trim();
55	  return custom || fallback;
56	}
57	
58	function pick(body: unknown, path: string): unknown {
59	  if (!path) return undefined;
60	  return path
61	    .split(".")
62	    .reduce<unknown>(
63	      (acc, key) =>
64	        acc && typeof acc === "object"
65	          ? (acc as Record<string, unknown>)[key]
66	          : undefined,
67	      body,
68	    );
69	}
70	
71	/** First array of objects that look like search hits, searched breadth-first. */
72	function findResultArray(body: unknown): unknown {
73	  const queue: unknown[] = [body];
74	  let steps = 0;
75	  while (queue.length && steps < 200) {
76	    steps += 1;
77	    const node = queue.shift();
78	    if (Array.isArray(node)) {
79	      const looksLikeHits = node.some(
80	        (item) =>
81	          item &&
82	          typeof item === "object" &&
83	          typeof (item as Record<string, unknown>).url === "string",
84	      );
85	      if (looksLikeHits) return node;
86	      continue;
87	    }
88	    if (node && typeof node === "object") {
89	      queue.push(...Object.values(node as Record<string, unknown>));
90	    }
91	  }
92	  return undefined;
93	}
94	
95	export const SEARCH_BACKENDS: Record<SearchBackendId, SearchBackendAdapter> = {
96	  tinyfish: {
97	    id: "tinyfish",
98	    label: "TinyFish",
99	    keyHint: "api.tinyfish.ai",
100	    defaultUrl: "https://api.search.tinyfish.ai/v1/search",
101	    buildRequest: (req, config) =>
102	      jsonPost(
103	        endpoint(config, "https://api.search.tinyfish.ai/v1/search"),
104	        { authorization: `Bearer ${config.apiKey}` },
105	        { query: req.query, context: req.context, num_results: req.maxResults },
106	      ),
107	    extract: (body) => (body as { results?: unknown })?.results,
108	  },
109	
110	  exa: {
111	    id: "exa",
112	    label: "Exa",
113	    keyHint: "exa.ai",
114	    defaultUrl: "https://api.exa.ai/search",
115	    buildRequest: (req, config) =>
116	      jsonPost(
117	        endpoint(config, "https://api.exa.ai/search"),
118	        { "x-api-key": config.apiKey },
119	        {
120	          query: req.query,
121	          numResults: req.maxResults,
122	          type: "auto",
123	          contents: { text: { maxCharacters: 600 } },
124	        },
125	      ),
126	    extract: (body) => (body as { results?: unknown })?.results,
127	  },
128	
129	  tavily: {
130	    id: "tavily",
131	    label: "Tavily",
132	    keyHint: "tavily.com",
133	    defaultUrl: "https://api.tavily.com/search",
134	    buildRequest: (req, config) =>
135	      jsonPost(
136	        endpoint(config, "https://api.tavily.com/search"),
137	        { authorization: `Bearer ${config.apiKey}` },
138	        {
139	          query: req.query,
140	          max_results: req.maxResults,
141	          search_depth: "advanced",
142	          include_answer: false,
143	        },
144	      ),
145	    extract: (body) => (body as { results?: unknown })?.results,
146	  },
147	
148	  brave: {
149	    id: "brave",
150	    label: "Brave Search",
151	    keyHint: "brave.com/search/api",
152	    defaultUrl: "https://api.search.brave.com/res/v1/web/search",
153	    buildRequest: (req, config) => {
154	      const base = endpoint(
155	        config,
156	        "https://api.search.brave.com/res/v1/web/search",
157	      );
158	      const url = new URL(base);
159	      url.searchParams.set("q", req.query);
160	      url.searchParams.set("count", String(req.maxResults));
161	      return {
162	        url: url.toString(),
163	        init: {
164	          method: "GET",
165	          headers: {
166	            accept: "application/json",
167	            "x-subscription-token": config.apiKey,
168	          },
169	        },
170	      };
171	    },
172	    extract: (body) => (body as { web?: { results?: unknown } })?.web?.results,
173	  },
174	
175	  serper: {
176	    id: "serper",
177	    label: "Serper",
178	    keyHint: "serper.dev",
179	    defaultUrl: "https://google.serper.dev/search",
180	    buildRequest: (req, config) =>
181	      jsonPost(
182	        endpoint(config, "https://google.serper.dev/search"),
183	        { "x-api-key": config.apiKey },
184	        { q: req.query, num: req.maxResults },
185	      ),
186	    extract: (body) => (body as { organic?: unknown })?.organic,
187	  },
188	
189	  custom: {
190	    id: "custom",
191	    label: "Custom JSON endpoint",
192	    keyHint: "your own search service",
193	    defaultUrl: "",
194	    requiresUrl: true,
195	    buildRequest: (req, config) =>
196	      jsonPost(
197	        config.baseUrl.trim(),
198	        config.apiKey ? { authorization: `Bearer ${config.apiKey}` } : {},
199	        { query: req.query, context: req.context, max_results: req.maxResults },
200	      ),
201	    extract: (body, config) =>
202	      pick(body, config.resultsPath) ?? findResultArray(body),
203	  },
204	};
205	
206	export const SEARCH_BACKEND_IDS = Object.keys(
207	  SEARCH_BACKENDS,
208	) as SearchBackendId[];
209	
210	export function searchBackend(id: SearchBackendId): SearchBackendAdapter {
211	  return SEARCH_BACKENDS[id] ?? SEARCH_BACKENDS.tinyfish;
212	}
213	
214	/**
215	 * Map one vendor's result object onto a Source. Field names vary enough
216	 * between vendors that this reads every spelling rather than per-adapter
217	 * mappers: a hit is a url plus whatever description the vendor supplies.
218	 */
219	export function toSource(value: unknown): Source | null {
220	  if (!value || typeof value !== "object") return null;
221	  const rec = value as Record<string, unknown>;
222	  const url = typeof rec.url === "string" ? rec.url.trim() : "";
223	  if (!/^https?:\/\//i.test(url)) return null;
224	  const str = (...keys: string[]): string => {
225	    for (const key of keys) {
226	      const v = rec[key];
227	      if (typeof v === "string" && v.trim()) return v.trim();
228	    }
229	    return "";
230	  };
231	  const title = str("title", "name", "heading");
232	  const snippet = str(
233	    "snippet",
234	    "description",
235	    "text",
236	    "content",
237	    "summary",
238	    "excerpt",
239	  );
240	  const source: Source = {
241	    title: title || url,
242	    url,
243	    snippet: snippet.slice(0, 1200),
244	  };
245	  const author = str("author", "byline");
246	  const publisher = str("publisher", "source", "site", "siteName");
247	  const date = str("date", "published", "publishedDate", "published_date");
248	  if (author) source.author = author;
249	  if (publisher) source.publisher = publisher;
250	  if (date) source.date = date;
251	  return source;
252	}
253	
254	export function toSources(value: unknown, maxResults: number): Source[] {
255	  if (!Array.isArray(value)) return [];
256	  const out: Source[] = [];
257	  const seen = new Set<string>();
258	  for (const item of value) {
259	    const source = toSource(item);
260	    if (!source || seen.has(source.url)) continue;
261	    seen.add(source.url);
262	    out.push(source);
263	    if (out.length >= maxResults) break;
264	  }
265	  return out;
266	}
267	
268	/** Run a search against whichever backend the writer configured. */
269	export async function runSearchBackend(
270	  req: SearchRequest,
271	  config: SearchBackendConfig,
272	): Promise<{ ok: true; results: Source[] } | { ok: false; message: string }> {
273	  const adapter = searchBackend(config.id);
274	  if (adapter.requiresUrl && !config.baseUrl.trim()) {
275	    return {
276	      ok: false,
277	      message: `${adapter.label} needs an endpoint URL in Settings.`,
