101	    fetchUrl: "https://api.tavily.com/extract",
102	    search: (key, query, _context, limit) => ({
103	      url: providerSearchUrl("https://api.tavily.com/search"),
104	      init: jsonPost({ authorization: `Bearer ${key}` }, {
105	        query,
106	        max_results: limit,
107	        search_depth: "advanced",
108	      }),
109	    }),
110	    path: (b) => (b as { results?: unknown })?.results,
111	  },
112	  brave: {
113	    searchUrl: "https://api.search.brave.com/res/v1/web/search",
114	    search: (key, query, _context, limit) => {
115	      const url = new URL(
116	        providerSearchUrl("https://api.search.brave.com/res/v1/web/search"),
117	      );
