149	      const rec = (b ?? {}) as Record<string, unknown>;
150	      for (const key of ["results", "sources", "data", "items", "hits"]) {
151	        if (Array.isArray(rec[key])) return rec[key];
152	      }
153	      return Array.isArray(b) ? b : undefined;
154	    },
155	  },
156	};
157	
158	function jsonPost(
159	  headers: Record<string, string>,
160	  body: unknown,
161	): RequestInit {
162	  return {
163	    method: "POST",
164	    headers: { "content-type": "application/json", ...headers },
165	    body: JSON.stringify(body),
166	  };
167	}
168	
169	function providerSearchUrl(fallback: string): string {
170	  return process.env.RESEARCH_SEARCH_URL?.trim() || fallback;
171	}
172	
173	function providerId(): ProviderId {
174	  const raw = (process.env.RESEARCH_PROVIDER ?? "tinyfish").trim().toLowerCase();
175	  return raw in PROVIDERS ? (raw as ProviderId) : "tinyfish";
176	}
177	
178	/** The configured key, falling back to the original TinyFish-only variable. */
179	export function researchApiKey(): string {
180	  return (
181	    process.env.RESEARCH_API_KEY?.trim() ||
182	    process.env.TINYFISH_API_KEY?.trim() ||
