187	function normalize(value: unknown, limit: number): Source[] {
188	  if (!Array.isArray(value)) return [];
189	  const out: Source[] = [];
190	  for (const item of value) {
191	    if (!item || typeof item !== "object") continue;
192	    const r = item as Record<string, unknown>;
193	    const url = typeof r.url === "string" ? r.url.trim() : "";
194	    if (!url) continue;
195	    const str = (...keys: string[]): string | undefined => {
196	      for (const key of keys) {
197	        const v = r[key];
198	        if (typeof v === "string" && v.trim()) return v.trim();
199	      }
200	      return undefined;
201	    };
202	    out.push({
203	      title: str("title", "name") ?? "(untitled)",
204	      url,
205	      snippet: str("snippet", "description", "text", "content", "summary") ?? "",
206	      author: str("author", "byline"),
