222	  try {
223	    const { url, init } = spec.search(key, query, context, 8);
224	    if (!url) return [];
225	    const res = await fetch(url, init);
226	    if (!res.ok) return [];
227	    return normalize(spec.path(await res.json()), 8);
228	  } catch {
229	    return [];
230	  }
231	}
232	
233	async function providerFetch(url: string): Promise<FetchedSource | null> {
234	  const key = researchApiKey();
235	  const spec = PROVIDERS[providerId()];
236	  const endpoint = process.env.RESEARCH_FETCH_URL?.trim() || spec.fetchUrl;
237	  if (!key || !endpoint) return null;
238	  try {
239	    const res = await fetch(endpoint, {
240	      method: "POST",
241	      headers: {
242	        "content-type": "application/json",
243	        authorization: `Bearer ${key}`,
244	      },
245	      body: JSON.stringify({ url, format: "markdown" }),
246	    });
247	    if (!res.ok) return null;
248	    const data = (await res.json()) as {
249	      title?: string;
250	      author?: string;
251	      publisher?: string;
252	      date?: string;
253	      markdown?: string;
254	      text?: string;
255	      embeddable?: boolean;
256	    };
257	    return {
258	      title: data.title ?? url,
259	      author: data.author,
260	      publisher: data.publisher,
261	      date: data.date,
262	      markdown: data.markdown ?? data.text ?? "",
263	      embeddable: data.embeddable ?? false,
264	    };
265	  } catch {
266	    return null;
267	  }
268	}
269	
270	/* ── Local fallback — always available, never calls the network ─ */
271	
272	function localSearch(query: string, context: string): Source[] {
273	  // Deterministic stub so the panel has something to render in dev.
274	  // The query and context are echoed in a way that proves the call worked.
275	  const slug =
276	    query
277	      .toLowerCase()
278	      .replace(/[^a-z0-9]+/g, "-")
279	      .replace(/^-+|-+$/g, "")
280	      .slice(0, 40) || "search";
281	  const trimmed = context.trim().slice(0, 80);
282	  return [
283	    {
284	      title: `Local stub: ${query}`,
285	      url: `https://example.invalid/${slug}`,
286	      snippet: trimmed
287	        ? `Set RESEARCH_API_KEY for live results. Echo of your context: ${trimmed}`
288	        : "Set RESEARCH_API_KEY to enable live research. This is a local stub.",
289	      publisher: "Twyne local",
290	    },
291	    {
292	      title: "Why the apparatus is a research tool",
293	      url: "https://twyne.love/docs/apparatus",
294	      snippet:
295	        "The Apparatus exists so writers can do research and build a bibliography while they write.",
296	      publisher: "Twyne",
297	      date: "2025",
298	    },
299	  ];
300	}
301	
302	function localFetch(url: string): FetchedSource {
303	  return {
304	    title: url,
305	    markdown: `# ${url}\n\n_Live fetch disabled. Set RESEARCH_API_KEY to pull clean markdown from this URL._`,
306	    embeddable: false,
307	  };
308	}
309	
310	/* ── Convex actions ───────────────────────────────────────────── */
311	
312	export const searchSources = action({
313	  args: { query: v.string(), context: v.optional(v.string()) },
314	  handler: async (
315	    ctx,
316	    args,
317	  ): Promise<{ results: Source[]; provider: string }> => {
318	    // Live research spends the TinyFish provider key, so it requires a
319	    // signed-in user. Pro subscribers get a higher rate-limit tier; signed-out
320	    // visitors (and local dev with no key) get the deterministic local stub
321	    // so the Apparatus never breaks.
322	    const identity = await ctx.auth.getUserIdentity();
323	
324	    // Rate limit on the host-provider path. The local stub is free and
325	    // unthrottled-by-design (it's what makes the Apparatus never break), but
326	    // the bucket is consumed first so a noisy client can't bypass via a
327	    // provider that happens to be configured.
328	    const isPro = identity
329	      ? await userIsPro(ctx, identity.tokenIdentifier)
330	      : false;
331	    if (identity) {
332	      await consumeRateLimit(ctx, {
333	        action: "research:search",
334	        identifier: identity.tokenIdentifier,
335	        ...(isPro ? RATE_LIMITS.research : RATE_LIMITS.researchFree),
336	      });
337	    }
338	
339	    if (identity && researchApiKey()) {
340	      const r = await providerSearch(args.query, args.context ?? "");
341	      if (r.length > 0) return { results: r, provider: "tinyfish" };
342	    }
343	    return {
344	      results: localSearch(args.query, args.context ?? ""),
345	      provider: "local",
346	    };
347	  },
348	});
349	
350	export const fetchSource = action({
351	  args: { url: v.string() },
352	  handler: async (
353	    ctx,
354	    args,
355	  ): Promise<FetchedSource & { provider: string }> => {
356	    const identity = await ctx.auth.getUserIdentity();
357	    const isPro = identity
358	      ? await userIsPro(ctx, identity.tokenIdentifier)
359	      : false;
360	    if (identity) {
361	      await consumeRateLimit(ctx, {
362	        action: "research:fetch",
363	        identifier: identity.tokenIdentifier,
364	        ...(isPro ? RATE_LIMITS.research : RATE_LIMITS.researchFree),
365	      });
366	    }
367	    if (identity && researchApiKey()) {
368	      const r = await providerFetch(args.url);
369	      if (r) return { ...r, provider: "tinyfish" };
370	    }
371	    return { ...localFetch(args.url), provider: "local" };
372	  },
373	});
374

