14	  disabled?: boolean;
15	  onGetSources$: PropFunction<() => void>;
16	  onAddMargin$: PropFunction<() => void>;
17	  onSendToPersona$: PropFunction<
18	    (personaId: string, personaName: string) => void
19	  >;
20	  onClose$: PropFunction<() => void>;
21	}
22	
23	interface SelectionActionsStore {
24	  personas: Persona[];
25	  personaOpen: boolean;
26	}
27	
28	/** A compact, manuscript-anchored action card for a selected passage. */
29	export const SelectionActions = component$<SelectionActionsProps>((props) => {
30	  const store = useStore<SelectionActionsStore>({
31	    personas: DEFAULT_PERSONAS,
32	    personaOpen: false,
33	  });
34	
35	  // eslint-disable-next-line qwik/no-use-visible-task
36	  useVisibleTask$(async () => {
37	    const custom = await loadPersonasFromIdb();
38	    if (custom?.length) store.personas = custom;
39	  });
40	
41	  const selection = props.selection;
42	  if (!selection) return null;
43	
44	  return (
45	    <div
46	      class={["selection-actions", `selection-actions--${selection.placement}`]}
47	      style={{ left: `${selection.x}px`, top: `${selection.y}px` }}
48	      role="toolbar"
49	      aria-label={`Actions for “${selection.text.slice(0, 70)}”`}
50	      // This must be declarative: a Qwik onMouseDown$ handler runs after the
51	      // browser has already collapsed the ProseMirror range. Keeping the
52	      // range lets every action act on the passage the writer just selected.
53	      preventdefault:mousedown
54	    >
55	      <div class="selection-actions__quote" title={selection.text}>
56	        “{selection.text.slice(0, 82)}
57	        {selection.text.length > 82 ? "…" : ""}”
58	      </div>
59	      <div class="selection-actions__row">
60	        <button
61	          type="button"
62	          onClick$={props.onGetSources$}
63	          disabled={props.disabled}
64	        >
65	          Get sources
66	        </button>
67	        <button
68	          type="button"
69	          onClick$={props.onAddMargin$}
